export const pdfReaderHtml = "<good-main-view title=\"PDF reader\" description=\"Open several local PDFs with the reusable GoodUI preview.\">\n  <good-section>\n    <good-breadcrumbs [items]=\"breadcrumbs\" />\n    <good-group title=\"Choose a document\" appearance=\"plain\">\n      <good-action-group orientation=\"responsive\">\n        @for (sample of samples; track sample.file) {\n          <good-button [variant]=\"selected().file === sample.file ? 'default' : 'outline'\"\n            (click)=\"choose(sample)\">{{ sample.name }}</good-button>\n        }\n      </good-action-group>\n      <good-alert tone=\"neutral\" appearance=\"light\" [title]=\"selected().name\"\n        [message]=\"selected().description + (pageCount() ? ' · ' + pageCount() + (pageCount() === 1 ? ' page ready' : ' pages ready') : '')\" />\n    </good-group>\n    <good-group title=\"Preview\" appearance=\"plain\">\n      <good-pdf-preview [source]=\"selected().file\" [title]=\"selected().name\" workerUrl=\"/pdf.worker.min.mjs\"\n        [downloadName]=\"selected().file.split('/').at(-1) ?? 'document.pdf'\"\n        (loaded)=\"pageCount.set($event)\" (loadError)=\"error.set($event)\" />\n      @if (error()) { <good-alert tone=\"destructive\" [message]=\"error()\" /> }\n    </good-group>\n    <good-group title=\"Use this example\" appearance=\"plain\">\n      <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"pdf-reader-page.html\"\n        [collapsible]=\"true\" [collapsedLines]=\"20\" />\n      <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"pdf-reader-page.ts\"\n        [collapsible]=\"true\" [collapsedLines]=\"20\" />\n    </good-group>\n  </good-section>\n</good-main-view>\n";
export const pdfReaderTs = "import { ChangeDetectionStrategy, Component, signal } from '@angular/core';\nimport {\n  GoodActionGroupComponent, GoodAlertComponent, GoodBreadcrumbsComponent, GoodButtonComponent,\n  GoodCodeBlockComponent, GoodGroupComponent, GoodMainViewComponent, GoodPdfPreviewComponent,\n  GoodSectionComponent, type GoodBreadcrumbItem,\n} from '@goodui/angular';\nimport { pdfReaderHtml, pdfReaderTs } from './source-code.generated';\n\ninterface SamplePdf { name: string; file: string; description: string }\n\n@Component({\n  selector: 'example-pdf-reader-page',\n  standalone: true,\n  imports: [GoodActionGroupComponent, GoodAlertComponent, GoodBreadcrumbsComponent, GoodButtonComponent,\n    GoodCodeBlockComponent, GoodGroupComponent, GoodMainViewComponent, GoodPdfPreviewComponent, GoodSectionComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './pdf-reader-page.html',\n})\nexport class PdfReaderPageComponent {\n  readonly breadcrumbs: readonly GoodBreadcrumbItem[] = [\n    { label: 'Home', route: '/dashboard' }, { label: 'Examples' }, { label: 'PDF reader' },\n  ];\n  readonly samples: readonly SamplePdf[] = [\n    { name: 'Welcome guide', file: '/pdf/welcome-guide.pdf', description: 'A two-page introduction' },\n    { name: 'Project report', file: '/pdf/project-report.pdf', description: 'A three-page status report' },\n    { name: 'Sample invoice', file: '/pdf/invoice-sample.pdf', description: 'A one-page invoice' },\n  ];\n  readonly selected = signal<SamplePdf>(this.samples[0]);\n  readonly pageCount = signal(0);\n  readonly error = signal('');\n  readonly htmlSource = pdfReaderHtml;\n  readonly typescriptSource = pdfReaderTs;\n\n  choose(sample: SamplePdf): void {\n    this.selected.set(sample);\n    this.pageCount.set(0);\n    this.error.set('');\n  }\n}\n";
